insert into reports.reporter (kind, key_hash, last_report_at, sys_status, sys_version, sys_created_at, sys_created_by, sys_modified_at, sys_modified_by)
select p.kind, p.key_hash, current_timestamp - min(r.age) * interval '1 minute', 'A', 1, current_timestamp, 'showcase', current_timestamp, 'showcase'
from showcase_person p join showcase_report r on r.person = p.person
group by p.kind, p.key_hash
on conflict do nothing;

insert into reports.report (reference_number, category_code, address, address_verified, latitude, longitude, description, reporter_contact, status, submission_key,
    municipality_code, municipality_name, channel, reporter_id, signed_digest, recipient_kind, recipient_name, published,
    sys_status, sys_version, sys_created_at, sys_created_by, sys_modified_at, sys_modified_by)
select v.ref, v.code, v.address, v.verified, v.lat, v.lon, v.description, v.contact, v.status, v.key,
    v.mcode, v.mname, v.channel, i.id, v.digest, v.rkind, v.rname, v.published,
    'A', 1, current_timestamp - v.age * interval '1 minute', 'resident', current_timestamp - v.age * interval '1 minute', 'resident'
from showcase_report v
left join showcase_person p on p.person = v.person
left join reports.reporter i on i.kind = p.kind and i.key_hash = p.key_hash
order by v.age desc;

